#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BMiraPierceTrialPreparationTests {
  static Type Model{get{var t=typeof(BMiraEquippedTrialContext).Assembly.GetType("LastRail.Battle.BMiraPierceTrialPreparation");Assert.That(t,Is.Not.Null,"Separate non-startable preparation context missing");return t;}}
  static object Call(string method,params object[] args){try{return Model.GetMethod(method).Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static readonly JObject nativeRun=JObject.Parse((string)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/MiraEquipped-20261016/NativeSource/server-packets.json"))["packets"]["grown"]["runSnapshot"]);
  static JObject NativeRun()=>(JObject)nativeRun.DeepClone();
  static object Prepare(string group,BMiraEquippedNativeFixture fixture)=>Call("Prepare",group,fixture.Source(),fixture.Node(),NativeRun(),BDirectAttackInput.Digest(nativeRun),ReadPolicy(ServerPolicy(),(string)ServerPolicy()["policyHash"]));
  static JObject State(object p)=>(JObject)p.GetType().GetMethod("Capture").Invoke(p,null);
  [TestCase("A_BASELINE","none",0)][TestCase("B_PIERCE","none",0)][TestCase("C_MULTISHOT","two",2500)][TestCase("D_COMBINED","two",2500)]
  public void FourApprovedGroupsPreserveVerifiedEquipmentAndRealNodeWithoutInventingOwnership(string group,string trial,int bps){var f=new BMiraEquippedNativeFixture(trial);var equipment=f.Source().Capture();var node=f.Node().Capture();var p=Prepare(group,f);var s=State(p);Assert.That((string)s["comparisonGroup"],Is.EqualTo(group));Assert.That((int)s["comparisonEquipment"]["coefficientBps"],Is.EqualTo(bps));Assert.That(JToken.DeepEquals(s["originalEquipmentContext"],equipment),Is.True);Assert.That(JToken.DeepEquals(s["originalNode"],node),Is.True);Assert.That((string)s["profile"],Is.EqualTo("mira-pierce-comparison-local.v1.20261016"));Assert.That((string)s["trialPolicyHash"],Is.EqualTo("a0de500d0c455d3332a5307097344712b540964db08a4e20f0db7c5a2167cdf5"));Assert.That(s["pierceOwnedSource"].Type,Is.EqualTo(JTokenType.Null));Assert.That(s["completedAttack"].Type,Is.EqualTo(JTokenType.Null));Assert.That((bool)s["canStart"],Is.False);Assert.That((bool)s["runtimeSupported"],Is.False);Assert.That((string)s["research"]["status"],Is.EqualTo("NOT_APPLICABLE"));Assert.That(s["research"]["modifiers"].Type,Is.EqualTo(JTokenType.Null));Assert.That((string)s["critical"]["status"],Is.EqualTo("NOT_APPLICABLE"));Assert.That(s["critical"]["chanceBps"].Type,Is.EqualTo(JTokenType.Null));Assert.That((int)s["critical"]["rngDraws"],Is.Zero);Assert.That((string)s["critical"]["policyVersion"],Is.EqualTo("combat.pierce-local-trial-policy.v1.20261016"));}
  [TestCase("A_BASELINE","two")][TestCase("B_PIERCE","two")][TestCase("C_MULTISHOT","none")][TestCase("D_COMBINED","one")][TestCase("UNKNOWN","none")]
  public void WrongGroupOrOriginalEnchantmentCannotBeRelabeled(string group,string trial){var f=new BMiraEquippedNativeFixture(trial);Assert.Throws<ArgumentException>(()=>Prepare(group,f));}
  [Test]public void PolicyAndOriginalNodeBindingsSurviveJsonAndRejectEvenRepinnedTamper(){var f=new BMiraEquippedNativeFixture("two");var p=Prepare("D_COMBINED",f);var s=JObject.Parse(State(p).ToString());string hash=BDirectAttackInput.Digest(s);var restored=Call("Restore",s,hash,"D_COMBINED",f.Source(),f.Node(),NativeRun(),BDirectAttackInput.Digest(nativeRun),ReadPolicy(ServerPolicy(),(string)ServerPolicy()["policyHash"]));Assert.That(JToken.DeepEquals(State(restored),s),Is.True);foreach(string key in new[]{"policy","node","profile","source","chance","group"}){var bad=(JObject)s.DeepClone();switch(key){case "policy":bad["critical"]["policyVersion"]=BMiraEquippedTrialContext.Policy;break;case "node":bad["originalNode"]["originalSource"]["origin"]["runId"]="OTHER_RUN";break;case "profile":bad["profile"]=BMiraEquippedTrialContext.Profile;break;case "source":bad["pierceOwnedSource"]=new JObject{["hasPierce"]=true};break;case "chance":bad["critical"]["chanceBps"]=0;break;case "group":bad["comparisonGroup"]="A_BASELINE";break;}Assert.Throws<ArgumentException>(()=>Call("Restore",bad,BDirectAttackInput.Digest(bad),"D_COMBINED",f.Source(),f.Node(),NativeRun(),BDirectAttackInput.Digest(nativeRun),ReadPolicy(ServerPolicy(),(string)ServerPolicy()["policyHash"])),key);}}
  [Test]public void DifferentOriginalNodeCannotBeAcceptedJustBecauseFixtureAccountAndRunIdsCoincide(){var f=new BMiraEquippedNativeFixture("none");Assert.Throws<ArgumentException>(()=>Call("Prepare","B_PIERCE",f.Source(),BMiraFirstNativeFixture.Node(),NativeRun(),BDirectAttackInput.Digest(nativeRun),ReadPolicy(ServerPolicy(),(string)ServerPolicy()["policyHash"])));}
  [TestCase("pin")][TestCase("origin")][TestCase("equipment")]
  public void NativeRunEvidenceMustUseIndependentPinAndOriginalBothDepartureBindings(string conflict){var f=new BMiraEquippedNativeFixture("none");var r=NativeRun();if(conflict=="origin")r["bCombatPin"]["origin"]["baseSnapshotHash"]=new string('0',64);if(conflict=="equipment")r["equipmentDeparturePin"]["pinHash"]=new string('0',64);string hash=conflict=="pin"?"sha256:"+new string('0',64):BDirectAttackInput.Digest(r);Assert.Throws<ArgumentException>(()=>Call("Prepare","B_PIERCE",f.Source(),f.Node(),r,hash,ReadPolicy(ServerPolicy(),(string)ServerPolicy()["policyHash"])));}
  static JObject ServerPolicy()=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/PierceV3-20261016/PolicySource/server-policy.json"))["policy"];
  static object ReadPolicy(JObject input,string hash){var type=typeof(BMiraEquippedTrialContext).Assembly.GetType("LastRail.Battle.BMiraPierceTrialPolicy");Assert.That(type,Is.Not.Null,"Actual Server policy reader missing");try{return type.GetMethod("Read").Invoke(null,new object[]{input,hash});}catch(TargetInvocationException e){throw e.InnerException;}}
  [Test]public void StrictServerPolicyReadPreservesActualSourceAndDetachedPolicy(){var original=ServerPolicy();var policy=ReadPolicy(original,(string)original["policyHash"]);var snapshot=(JObject)policy.GetType().GetMethod("Capture").Invoke(policy,null);Assert.That(JToken.DeepEquals(original,snapshot),Is.True);snapshot["critical"]["rngDraws"]=1;Assert.That(JToken.DeepEquals(original,(JObject)policy.GetType().GetMethod("Capture").Invoke(policy,null)),Is.True);}
  [Test]public void StrictServerPolicyRejectsEvenRepinnedChanceProfileAndUnknownPolicy(){foreach(var kind in new[]{"chance","profile","unknown"}){var p=ServerPolicy();if(kind=="chance")p["critical"]["chanceBps"]=0;if(kind=="profile")p["profile"]=BMiraEquippedTrialContext.Profile;if(kind=="unknown")p["unexpected"]=true;var body=(JObject)p.DeepClone();body.Remove("policyHash");p["policyHash"]=BDirectAttackInput.Digest(body).Substring(7);Assert.Throws<ArgumentException>(()=>ReadPolicy(p,(string)p["policyHash"]),kind);}}
  [Test]public void CapturedCopiesCannotChangePolicyStatsOrOriginalPackets(){var f=new BMiraEquippedNativeFixture("none");var p=Prepare("B_PIERCE",f);var before=State(p);var copy=State(p);copy["critical"]["rngDraws"]=1;copy["originalEquipmentContext"]["start"]["source"]["effectiveStats"]["maxHp"]=1;copy["originalNode"]["originalSource"]["origin"]["runId"]="CHANGED";Assert.That(JToken.DeepEquals(before,State(p)),Is.True);var method=p.GetType().GetMethod("RequireRuntimeReady");Assert.That(method,Is.Not.Null);var ex=Assert.Throws<TargetInvocationException>(()=>method.Invoke(p,null));Assert.That(ex.InnerException,Is.TypeOf<InvalidOperationException>());}
 }
}
#endif